messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: libtiff/tif_extension.c
Line: 104
Function: TIFFSetClientInfo
Bug type: null-pointer-dereference
CWE: CWE-476
Explanation: If the caller passes name == NULL and no existing link is found (or list is empty), strlen(name) is called when allocating the name buffer, dereferencing a NULL pointer.

Source context:
```c
       64: void *TIFFGetClientInfo(TIFF *tif, const char *name)
       65: 
       66: {
       67:     TIFFClientInfoLink *psLink = tif->tif_clientinfo;
       68: 
       69:     while (psLink != NULL && strcmp(psLink->name, name) != 0)
       70:         psLink = psLink->next;
       71: 
       72:     if (psLink != NULL)
       73:         return psLink->data;
       74:     else
       75:         return NULL;
       76: }
       77: 
       78: void TIFFSetClientInfo(TIFF *tif, void *data, const char *name)
       79: 
       80: {
       81:     TIFFClientInfoLink *psLink = tif->tif_clientinfo;
       82: 
       83:     /*
       84:     ** Do we have an existing link with this name?  If so, just
       85:     ** set it.
       86:     */
       87:     while (psLink != NULL && strcmp(psLink->name, name) != 0)
       88:         psLink = psLink->next;
       89: 
       90:     if (psLink != NULL)
       91:     {
       92:         psLink->data = data;
       93:         return;
       94:     }
       95: 
       96:     /*
       97:     ** Create a new link.
       98:     */
       99: 
      100:     psLink =
      101:         (TIFFClientInfoLink *)_TIFFmallocExt(tif, sizeof(TIFFClientInfoLink));
      102:     assert(psLink != NULL);
      103:     psLink->next = tif->tif_clientinfo;
>>>   104:     psLink->name = (char *)_TIFFmallocExt(tif, (tmsize_t)(strlen(name) + 1));
      105:     assert(psLink->name != NULL);
      106:     strcpy(psLink->name, name);
      107:     psLink->data = data;
      108: 
      109:     tif->tif_clientinfo = psLink;
      110: }
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libtiff_upstream reproducer.c -L/tmp/libtiff_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libtiff_upstream
